// ---------- patterns and matching ----------

type termKind int

const (
	tFuzzy termKind = iota
	tExact
	tPrefix
	tSuffix
	tEqual
)

type Term struct {
	Kind     termKind
	Text     []rune
	Inverse  bool
	CaseSens bool
}

type Pattern struct {
	// OR-groups; each group is a list of terms which are OR'd together;
	// groups are AND'd together.
	Groups    [][]Term
	CaseMode  int // 0=smart, 1=ignore, 2=strict
	Extended  bool
	Exact     bool
}

func buildPattern(query string, opts *Options) *Pattern {
	p := &Pattern{Extended: opts.Extended, Exact: opts.Exact, CaseMode: opts.IgnoreCase}
	if !opts.Extended {
		// Single fuzzy or exact term
		t := Term{Text: []rune(query)}
		if opts.Exact {
			t.Kind = tExact
		} else {
			t.Kind = tFuzzy
		}
		t.CaseSens = termCaseSensitive(opts.IgnoreCase, t.Text)
		if len(t.Text) > 0 {
			p.Groups = [][]Term{{t}}
		}
		return p
	}
	// Extended: split by spaces, handle | for OR groups
	tokens := splitTokens(query)
	var groups [][]Term
	var current []Term
	for _, tok := range tokens {
		if tok == "|" {
			continue
		}
		t := parseTerm(tok, opts)
		if t == nil {
			continue
		}
		current = append(current, *t)
		// Check if next is |
	}
	// Re-parse properly with OR handling
	current = nil
	groups = nil
	i := 0
	for i < len(tokens) {
		tok := tokens[i]
		if tok == "|" {
			// absorb into last group
			i++
			continue
		}
		t := parseTerm(tok, opts)
		if t == nil { i++; continue }
		// Check if preceded by "|" or followed by "|"
		prevPipe := i > 0 && tokens[i-1] == "|"
		nextPipe := i+1 < len(tokens) && tokens[i+1] == "|"
		if prevPipe && len(groups) > 0 {
			groups[len(groups)-1] = append(groups[len(groups)-1], *t)
		} else if nextPipe {
			groups = append(groups, []Term{*t})
		} else {
			groups = append(groups, []Term{*t})
		}
		i++
	}
	p.Groups = groups
	return p
}

func splitTokens(s string) []string {
	// respect backslash escapes of spaces
	var tokens []string
	var cur strings.Builder
	escaped := false
	for _, r := range s {
		if escaped {
			cur.WriteRune(r)
			escaped = false
			continue
		}
		if r == '\\' {
			escaped = true
			continue
		}
		if r == ' ' {
			if cur.Len() > 0 {
				tokens = append(tokens, cur.String())
				cur.Reset()
			}
			continue
		}
		cur.WriteRune(r)
	}
	if cur.Len() > 0 {
		tokens = append(tokens, cur.String())
	}
	return tokens
}

func parseTerm(tok string, opts *Options) *Term {
	if tok == "" || tok == "|" {
		return nil
	}
	t := &Term{}
	s := tok
	if strings.HasPrefix(s, "!") {
		t.Inverse = true
		s = s[1:]
	}
	defaultExact := opts.Exact
	// Determine kind
	switch {
	case strings.HasPrefix(s, "'"):
		s = s[1:]
		if defaultExact {
			t.Kind = tFuzzy
		} else {
			t.Kind = tExact
		}
	case strings.HasPrefix(s, "^") && strings.HasSuffix(s, "$") && len(s) > 1:
		s = s[1 : len(s)-1]
		t.Kind = tEqual
	case strings.HasPrefix(s, "^"):
		s = s[1:]
		t.Kind = tPrefix
	case strings.HasSuffix(s, "$"):
		s = s[:len(s)-1]
		t.Kind = tSuffix
	default:
		if defaultExact {
			t.Kind = tExact
		} else {
			t.Kind = tFuzzy
		}
	}
	if s == "" {
		return nil
	}
	t.Text = []rune(s)
	t.CaseSens = termCaseSensitive(opts.IgnoreCase, t.Text)
	return t
}

func termCaseSensitive(mode int, text []rune) bool {
	if mode == 1 {
		return false
	}
	if mode == 2 {
		return true
	}
	// smart case: case-sensitive if any upper
	for _, r := range text {
		if unicode.IsUpper(r) {
			return true
		}
	}
	return false
}

// ---------- scoring / matching ----------

// Bonus constants (inspired by fzf's default scoring)
const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1
	bonusBoundary     = scoreMatch / 2
	bonusNonWord      = scoreMatch / 2
	bonusCamel123     = bonusBoundary + scoreGapExtension
	bonusConsecutive  = -(scoreGapStart + scoreGapExtension)
	bonusFirstCharMultiplier = 2
)

func charClass(r rune) int {
	// 0=white, 1=non-word, 2=lower, 3=upper, 4=digit
	switch {
	case r == ' ' || r == '\t' || r == '\n':
		return 0
	case unicode.IsLower(r):
		return 2
	case unicode.IsUpper(r):
		return 3
	case unicode.IsDigit(r):
		return 4
	case unicode.IsLetter(r):
		return 2
	default:
		return 1
	}
}

func bonusFor(prev, curr int) int {
	if prev == 0 && curr != 0 {
		return bonusBoundary
	}
	if (prev == 2 && curr == 3) || (prev != 4 && curr == 4) {
		return bonusCamel123
	}
	if curr == 1 {
		return bonusNonWord
	}
	if prev == 1 {
		return bonusBoundary
	}
	return 0
}

func normalizeRune(r rune, caseSens bool) rune {
	if !caseSens {
		r = unicode.ToLower(r)
	}
	return r
}

// fuzzyMatch returns (score, startPos, endPos). If no match, score is math.MinInt and endPos is -1.
func fuzzyMatch(text string, query []rune, caseSens bool) (int, int, int) {
	if len(query) == 0 {
		return 0, 0, 0
	}
	textR := []rune(text)
	// Try to find best match using a simple left-to-right greedy + score evaluation
	// Actually do the full FZF v2-like DP for best accuracy? That's complex. Let's do a simpler approach:
	// 1. Find first possible starting index by matching query greedily from left
	// 2. Find best ending by extending greedily backwards
	// 3. Compute score along the chosen indices
	sidx := -1
	qi := 0
	for i, r := range textR {
		rn := normalizeRune(r, caseSens)
		qr := normalizeRune(query[qi], caseSens)
		if rn == qr {
			if sidx < 0 {
				sidx = i
			}
			qi++
			if qi == len(query) {
				break
			}
		}
	}
	if qi < len(query) {
		return -1 << 30, -1, -1
	}
	// eidx: find first position where all query chars have been consumed
	// Then refine by walking back from right
	// Find eidx via greedy from the right
	eidx := len(textR)
	qj := len(query) - 1
	for i := len(textR) - 1; i >= 0; i-- {
		rn := normalizeRune(textR[i], caseSens)
		qr := normalizeRune(query[qj], caseSens)
		if rn == qr {
			eidx = i + 1
			qj--
			if qj < 0 {
				break
			}
		}
	}
	if qj >= 0 {
		return -1 << 30, -1, -1
	}
	sidx = len(textR) - 1
	qj = len(query) - 1
	for i := eidx - 1; i >= 0; i-- {
		rn := normalizeRune(textR[i], caseSens)
		qr := normalizeRune(query[qj], caseSens)
		if rn == qr {
			sidx = i
			qj--
			if qj < 0 {
				break
			}
		}
	}
	// Now compute score
	score := 0
	consecutive := 0
	prevClass := 0
	inGap := false
	qi = 0
	for i := sidx; i < eidx; i++ {
		r := textR[i]
		cls := charClass(r)
		rn := normalizeRune(r, caseSens)
		qr := normalizeRune(query[qi], caseSens)
		if rn == qr {
			s := scoreMatch
			bonus := bonusFor(prevClass, cls)
			if i == sidx {
				bonus *= bonusFirstCharMultiplier
			}
			if consecutive == 0 {
				// gap ended; use boundary-based bonus
				s += bonus
			} else {
				// consecutive match
				if bonus > bonusConsecutive {
					s += bonus
				} else {
					s += bonusConsecutive
				}
			}
			score += s
			consecutive++
			inGap = false
			qi++
			if qi == len(query) {
				break
			}
		} else {
			if inGap {
				score += scoreGapExtension
			} else {
				score += scoreGapStart
			}
			inGap = true
			consecutive = 0
		}
		prevClass = cls
	}
	return score, sidx, eidx
}

// exactMatch returns score,pos or -inf,-1 if no match
func exactMatch(text string, query []rune, caseSens bool) (int, int, int) {
	if len(query) == 0 {
		return 0, 0, 0
	}
	textR := []rune(text)
	qlen := len(query)
	best := -1 << 30
	bs, be := -1, -1
	for i := 0; i+qlen <= len(textR); i++ {
		match := true
		for k := 0; k < qlen; k++ {
			if normalizeRune(textR[i+k], caseSens) != normalizeRune(query[k], caseSens) {
				match = false
				break
			}
		}
		if match {
			// Compute score with bonuses
			score := 0
			prevClass := 0
			if i > 0 {
				prevClass = charClass(textR[i-1])
			}
			for k := 0; k < qlen; k++ {
				cls := charClass(textR[i+k])
				s := scoreMatch
				bonus := bonusFor(prevClass, cls)
				if k == 0 {
					bonus *= bonusFirstCharMultiplier
					s += bonus
				} else {
					if bonus > bonusConsecutive {
						s += bonus
					} else {
						s += bonusConsecutive
					}
				}
				score += s
				prevClass = cls
			}
			if score > best {
				best = score
				bs = i
				be = i + qlen
			}
		}
	}
	if best == -1<<30 {
		return -1 << 30, -1, -1
	}
	return best, bs, be
}

func prefixMatch(text string, query []rune, caseSens bool) (int, int, int) {
	textR := []rune(text)
	if len(textR) < len(query) {
		return -1 << 30, -1, -1
	}
	// allow leading whitespace skip
	start := 0
	for start < len(textR) && (textR[start] == ' ' || textR[start] == '\t') {
		start++
	}
	if len(textR)-start < len(query) {
		return -1 << 30, -1, -1
	}
	for k := 0; k < len(query); k++ {
		if normalizeRune(textR[start+k], caseSens) != normalizeRune(query[k], caseSens) {
			return -1 << 30, -1, -1
		}
	}
	score := len(query)*scoreMatch + bonusBoundary*bonusFirstCharMultiplier + (len(query)-1)*bonusConsecutive
	return score, start, start + len(query)
}

func suffixMatch(text string, query []rune, caseSens bool) (int, int, int) {
	textR := []rune(text)
	// trim trailing whitespace
	end := len(textR)
	for end > 0 && (textR[end-1] == ' ' || textR[end-1] == '\t') {
		end--
	}
	if end-0 < len(query) {
		return -1 << 30, -1, -1
	}
	start := end - len(query)
	for k := 0; k < len(query); k++ {
		if normalizeRune(textR[start+k], caseSens) != normalizeRune(query[k], caseSens) {
			return -1 << 30, -1, -1
		}
	}
	score := len(query)*scoreMatch + (len(query)-1)*bonusConsecutive
	return score, start, end
}

func equalMatch(text string, query []rune, caseSens bool) (int, int, int) {
	textR := []rune(text)
	// skip whitespace
	start := 0
	for start < len(textR) && (textR[start] == ' ' || textR[start] == '\t') {
		start++
	}
	end := len(textR)
	for end > start && (textR[end-1] == ' ' || textR[end-1] == '\t') {
		end--
	}
	if end-start != len(query) {
		return -1 << 30, -1, -1
	}
	for k := 0; k < len(query); k++ {
		if normalizeRune(textR[start+k], caseSens) != normalizeRune(query[k], caseSens) {
			return -1 << 30, -1, -1
		}
	}
	score := len(query)*scoreMatch + bonusBoundary*bonusFirstCharMultiplier + (len(query)-1)*bonusConsecutive
	return score, start, end
}

func matchTerm(text string, t Term) (int, int, int, bool) {
	var score, s, e int
	switch t.Kind {
	case tFuzzy:
		score, s, e = fuzzyMatch(text, t.Text, t.CaseSens)
	case tExact:
		score, s, e = exactMatch(text, t.Text, t.CaseSens)
	case tPrefix:
		score, s, e = prefixMatch(text, t.Text, t.CaseSens)
	case tSuffix:
		score, s, e = suffixMatch(text, t.Text, t.CaseSens)
	case tEqual:
		score, s, e = equalMatch(text, t.Text, t.CaseSens)
	}
	matched := score > -1<<29
	if t.Inverse {
		if matched {
			return 0, -1, -1, false
		}
		return 0, 0, 0, true
	}
	return score, s, e, matched
}

// matches returns (total_score, matched)
func matchPattern(text string, p *Pattern) (int, bool) {
	if len(p.Groups) == 0 {
		return 0, true
	}
	total := 0
	for _, group := range p.Groups {
		bestScore := -1 << 30
		anyMatch := false
		for _, t := range group {
			score, _, _, ok := matchTerm(text, t)
			if ok {
				anyMatch = true
				if score > bestScore {
					bestScore = score
				}
			}
		}
		if !anyMatch {
			return 0, false
		}
		total += bestScore
	}
	return total, true
}

// ---------- nth/delimiter transformations ----------

type NthRange struct {
	Begin int  // 1-based, negative counts from end; 0 means unset (use 1)
	End   int  // 1-based, negative counts from end; 0 means unset (use last)
	Single bool
}

func parseNth(spec string) []NthRange {
	if spec == "" {
		return nil
	}
	parts := strings.Split(spec, ",")
	var rs []NthRange
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" { continue }
		if strings.Contains(p, "..") {
			ab := strings.SplitN(p, "..", 2)
			var a, b int
			if ab[0] == "" { a = 1 } else { a, _ = strconv.Atoi(ab[0]) }
			if ab[1] == "" { b = -1 } else { b, _ = strconv.Atoi(ab[1]) }
			rs = append(rs, NthRange{Begin: a, End: b})
		} else {
			n, err := strconv.Atoi(p)
			if err == nil {
				rs = append(rs, NthRange{Begin: n, End: n, Single: true})
			}
		}
	}
	return rs
}

func splitFields(line, delim string) []string {
	if delim == "" {
		// AWK-style: split on whitespace, but preserve the trailing whitespace as part of field
		// For simplicity: split on single-or-multiple whitespace but keep trailing whitespace attached
		var fields []string
		i := 0
		n := len(line)
		for i < n {
			// skip over whitespace to get start of next field after previous
			// Actually AWK-style: fields separated by runs of whitespace
			// For our simplified version: split on runs of spaces/tabs
			start := i
			for i < n && line[i] != ' ' && line[i] != '\t' {
				i++
			}
			if i > start {
				// include trailing whitespace
				for i < n && (line[i] == ' ' || line[i] == '\t') {
					i++
				}
				fields = append(fields, line[start:i])
			} else {
				// line starts with whitespace; attach to first field
				for i < n && (line[i] == ' ' || line[i] == '\t') {
					i++
				}
				if i < n {
					start = i
					for i < n && line[i] != ' ' && line[i] != '\t' {
						i++
					}
					for i < n && (line[i] == ' ' || line[i] == '\t') {
						i++
					}
					fields = append(fields, line[:i])
					_ = start
				}
			}
		}
		return fields
	}
	// Treat delim as literal string (simplified; doesn't support full regex)
	// Split such that delim is included at end of each field except maybe last
	var fields []string
	rem := line
	for {
		idx := strings.Index(rem, delim)
		if idx < 0 {
			if rem != "" {
				fields = append(fields, rem)
			}
			break
		}
		fields = append(fields, rem[:idx+len(delim)])
		rem = rem[idx+len(delim):]
	}
	return fields
}

func applyNth(line string, ranges []NthRange, delim string) string {
	if len(ranges) == 0 {
		return line
	}
	fields := splitFields(line, delim)
	if len(fields) == 0 {
		return line
	}
	var parts []string
	for _, r := range ranges {
		b, e := r.Begin, r.End
		if b < 0 { b = len(fields) + b + 1 }
		if e < 0 { e = len(fields) + e + 1 }
		if b < 1 { b = 1 }
		if e > len(fields) { e = len(fields) }
		if b > len(fields) { continue }
		for i := b - 1; i < e; i++ {
			parts = append(parts, fields[i])
		}
	}
	return strings.Join(parts, "")
}

// ---------- Items and matching pipeline ----------

type Item struct {
	Raw     string
	Display string // after --with-nth transform
	Match   string // after --nth transform (what we match against)
	Index   int
	Score   int
	MatchS  int
	MatchE  int
}

// ---------- runFilter ----------

func readAll(r io.Reader, read0 bool) []string {
	br := bufio.NewReader(r)
	var lines []string
	if read0 {
		var cur strings.Builder
		for {
			b, err := br.ReadByte()
			if err != nil {
				if cur.Len() > 0 { lines = append(lines, cur.String()) }
				break
			}
			if b == 0 {
				lines = append(lines, cur.String())
				cur.Reset()
			} else {
				cur.WriteByte(b)
			}
		}
	} else {
		for {
			line, err := br.ReadString('\n')
			if err != nil {
				if line != "" { lines = append(lines, strings.TrimRight(line, "\r\n")) }
				break
			}
			lines = append(lines, strings.TrimRight(line, "\r\n"))
		}
	}
	return lines
}

func runFilter(query string, opts *Options) int {
	pattern := buildPattern(query, opts)
	lines := readAll(os.Stdin, opts.Read0)

	nthRanges := parseNth(opts.NthSpec)
	withNthRanges := parseNth(opts.WithNthSpec)
	acceptNthRanges := parseNth(opts.AcceptNth)

	items := make([]Item, 0, len(lines))
	for i, line := range lines {
		it := Item{Raw: line, Index: i}
		it.Display = line
		if len(withNthRanges) > 0 {
			it.Display = applyNth(line, withNthRanges, opts.Delimiter)
		}
		it.Match = it.Display
		if len(nthRanges) > 0 {
			it.Match = applyNth(it.Display, nthRanges, opts.Delimiter)
		}
		score, ok := matchPattern(it.Match, pattern)
		if !ok {
			continue
		}
		it.Score = score
		items = append(items, it)
	}

	if opts.Tac {
		// reverse order (applies to input order)
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
			items[i].Index, items[j].Index = items[j].Index, items[i].Index
		}
	}

	if opts.Sort && len(pattern.Groups) > 0 {
		sort.SliceStable(items, func(i, j int) bool {
			if items[i].Score != items[j].Score {
				return items[i].Score > items[j].Score
			}
			return applyTiebreak(items[i], items[j], opts.Tiebreak)
		})
	}

	if opts.PrintQuery {
		fmt.Println(query)
	}

	var out []string
	for _, it := range items {
		s := it.Display
		if len(acceptNthRanges) > 0 {
			s = applyNth(it.Raw, acceptNthRanges, opts.Delimiter)
		}
		out = append(out, s)
	}

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	sep := byte('\n')
	if opts.Print0 { sep = 0 }
	for _, s := range out {
		w.WriteString(s)
		w.WriteByte(sep)
	}
	if len(out) == 0 {
		return 1
	}
	return 0
}

func applyTiebreak(a, b Item, crit []string) bool {
	for _, c := range crit {
		switch c {
		case "length":
			la := len([]rune(a.Match))
			lb := len([]rune(b.Match))
			if la != lb { return la < lb }
		case "index":
			if a.Index != b.Index { return a.Index < b.Index }
		case "begin":
			if a.MatchS != b.MatchS { return a.MatchS < b.MatchS }
		case "end":
			if a.MatchE != b.MatchE { return a.MatchE > b.MatchE }
		}
	}
	return a.Index < b.Index
}

func main() {
	args := os.Args[1:]
	opts := parseOpts(args)

	if opts.Filter != nil {
		q := *opts.Filter
		if q == "" && opts.Query != "" {
			q = opts.Query
		}
		os.Exit(runFilter(q, opts))
	}

	// Non-filter interactive mode is out of scope for this reimplementation.
	// Bail with a TTY error like fzf does when stdin isn't a TTY.
	fmt.Fprintln(os.Stderr, "inappropriate ioctl for device")
	os.Exit(2)
}
