			} else {
				key = a
			}
		} else if strings.HasPrefix(a, "-") && len(a) > 2 && a[1] != '-' {
			// short opt with attached value like -fabc or -qabc
			key = a[:2]
			val = a[2:]
			hasEq = true
		} else if strings.HasPrefix(a, "+") && len(a) > 2 {
			key = a[:2]
			val = a[2:]
			hasEq = true
		} else {
