			} else {
				// consume next arg if present and doesn't look like option
				if i+1 < len(args) {
					nxt := args[i+1]
					if !strings.HasPrefix(nxt, "-") || nxt == "-" {
						v = nxt
						i++
					} else if nxt == "" {
						v = nxt
						i++
					} else {
