//go:embed assets/version.txt
var versionText string

//go:embed assets/bash.sh
var bashScript string

//go:embed assets/zsh.sh
var zshScript string

//go:embed assets/fish.sh
var fishScript string

// ---------- option parsing ----------

type Options struct {
	Filter      *string
	Query       string
	PrintQuery  bool
	Extended    bool
	Exact       bool
	IgnoreCase  int // 0=smart, 1=ignore, 2=strict
	Sort        bool
	Tac         bool
	Tiebreak    []string
	Multi       bool
	Select1     bool
	Exit0       bool
	NthSpec     string
	WithNthSpec string
	AcceptNth   string
	Delimiter   string
	Print0      bool
	Read0       bool
	Scheme      string
	Reverse     bool
	Layout      string
}

func defaultOpts() *Options {
	return &Options{
		Extended:   true,
		Sort:       true,
		IgnoreCase: 0,
		Tiebreak:   []string{"length"},
		Scheme:     "default",
		Layout:     "default",
	}
}

func errExit(msg string, code int) {
	fmt.Fprintln(os.Stderr, msg)
	os.Exit(code)
}

// parse options; returns Options
func parseOpts(args []string) *Options {
	o := defaultOpts()
	i := 0
	needArg := func(name string) string {
		i++
		if i >= len(args) {
			errExit("missing value for "+name, 2)
		}
		return args[i]
	}
	for i < len(args) {
		a := args[i]
		// Handle --opt=val form
		var key, val string
		hasEq := false
		if strings.HasPrefix(a, "--") {
			if eq := strings.Index(a, "="); eq >= 0 {
				key = a[:eq]
				val = a[eq+1:]
				hasEq = true
			} else {
				key = a
			}
		} else if strings.HasPrefix(a, "-") && len(a) > 2 && a[1] != '-' {
			// short opt with attached value like -fabc or -qabc
			key = a[:2]
			val = a[2:]
			hasEq = true
		} else if strings.HasPrefix(a, "+") && len(a) > 2 {
			key = a[:2]
			val = a[2:]
			hasEq = true
		} else {
			key = a
		}

		switch key {
		case "--help":
			fmt.Print(helpText)
			os.Exit(0)
		case "--version":
			fmt.Print(versionText)
			os.Exit(0)
		case "--man":
			// minimal man fallback
			fmt.Println("No manual entry for fzf")
			os.Exit(0)
		case "--bash":
			fmt.Print(bashScript)
			os.Exit(0)
		case "--zsh":
			fmt.Print(zshScript)
			os.Exit(0)
		case "--fish":
			fmt.Print(fishScript)
			os.Exit(0)
		case "-f", "--filter":
			var v string
			if hasEq {
				v = val
			} else {
				// consume next arg if present and doesn't look like option
				if i+1 < len(args) {
					nxt := args[i+1]
					if !strings.HasPrefix(nxt, "-") || nxt == "-" {
						v = nxt
						i++
					} else if nxt == "" {
						v = nxt
						i++
					} else {
						errExit("query string required", 2)
					}
				} else {
					errExit("query string required", 2)
				}
			}
			o.Filter = &v
		case "-q", "--query":
			if hasEq {
				o.Query = val
			} else {
				o.Query = needArg(key)
			}
		case "--print-query":
			o.PrintQuery = true
		case "-e", "--exact":
			o.Exact = true
		case "-x", "--extended":
			o.Extended = true
		case "+x", "--no-extended":
			o.Extended = false
		case "-i", "--ignore-case":
			o.IgnoreCase = 1
		case "+i", "--no-ignore-case":
			o.IgnoreCase = 2
		case "--smart-case":
			o.IgnoreCase = 0
		case "-s", "--sort":
			o.Sort = true
		case "+s", "--no-sort":
			o.Sort = false
		case "--tac":
			o.Tac = true
		case "--no-tac":
			o.Tac = false
		case "--tiebreak":
			var v string
			if hasEq { v = val } else { v = needArg(key) }
			o.Tiebreak = strings.Split(v, ",")
		case "-m", "--multi":
			o.Multi = true
		case "+m", "--no-multi":
			o.Multi = false
		case "-1", "--select-1":
			o.Select1 = true
		case "+1", "--no-select-1":
			o.Select1 = false
		case "-0", "--exit-0":
			o.Exit0 = true
		case "+0", "--no-exit-0":
			o.Exit0 = false
		case "-n", "--nth":
			if hasEq { o.NthSpec = val } else { o.NthSpec = needArg(key) }
		case "--with-nth":
			if hasEq { o.WithNthSpec = val } else { o.WithNthSpec = needArg(key) }
		case "--accept-nth":
			if hasEq { o.AcceptNth = val } else { o.AcceptNth = needArg(key) }
		case "-d", "--delimiter":
			if hasEq { o.Delimiter = val } else { o.Delimiter = needArg(key) }
		case "--read0":
			o.Read0 = true
		case "--print0":
			o.Print0 = true
		case "--no-read0":
			o.Read0 = false
		case "--no-print0":
			o.Print0 = false
		case "--ansi", "--no-ansi", "--literal", "--no-literal",
			"--disabled", "--no-disabled", "--sync", "--no-sync",
			"--cycle", "--no-cycle", "--wrap", "--no-wrap",
			"--highlight-line", "--no-highlight-line",
			"--track", "--no-track", "--raw", "--no-raw",
			"--no-multi-line", "--multi-line",
			"--keep-right", "--no-keep-right",
			"--no-hscroll", "--hscroll",
			"--filepath-word", "--no-filepath-word",
			"--header-first", "--no-header-first",
			"--no-color", "--no-bold", "--bold",
			"--no-scrollbar",
			"--no-input", "--input",
			"--no-separator",
			"--reverse":
			// boolean toggles, mostly no-ops for non-interactive filter mode
			if key == "--reverse" { o.Reverse = true }
		case "--scheme":
			if hasEq { o.Scheme = val } else { o.Scheme = needArg(key) }
		case "--layout":
			if hasEq { o.Layout = val } else { o.Layout = needArg(key) }
		default:
			// Accept but ignore any option that takes a value (for TUI-only options).
			// If the arg looks unknown and isn't a recognized ignored option, error out.
			if !isIgnorableOption(key) {
				errExit("unknown option: "+a, 2)
			}
			// Some ignorable options take a value we need to consume
			if !hasEq && optTakesValue(key) {
				if i+1 < len(args) {
					i++
				}
			}
		}
		i++
	}
	return o
}

// Options that we accept but ignore (no effect in filter mode)
// Many of these are TUI-only settings.
func isIgnorableOption(k string) bool {
	for _, p := range ignorableOpts {
		if k == p {
			return true
		}
	}
	return false
}

func optTakesValue(k string) bool {
	for _, p := range ignorableOptsWithValue {
		if k == p {
			return true
		}
	}
	return false
}

var ignorableOptsWithValue = []string{
	"--height", "--min-height", "--tmux", "--color", "--style",
	"--margin", "--padding", "--border", "--border-label", "--border-label-pos",
	"--list-border", "--list-label", "--list-label-pos",
	"--input-border", "--input-label", "--input-label-pos",
	"--header-border", "--header-lines-border", "--header-label", "--header-label-pos",
	"--footer", "--footer-border", "--footer-label", "--footer-label-pos",
	"--preview", "--preview-window", "--preview-border", "--preview-label", "--preview-label-pos",
	"--header", "--header-lines",
	"--prompt", "--pointer", "--marker", "--marker-multi-line", "--ellipsis",
	"--tabstop", "--separator", "--ghost", "--info", "--info-command",
	"--scrollbar", "--gutter", "--gutter-raw", "--gap", "--gap-line",
	"--wrap-sign", "--scroll-off", "--hscroll-off", "--jump-labels",
	"--expect", "--bind", "--with-shell", "--listen", "--listen-unsafe",
	"--walker", "--walker-root", "--walker-skip",
