var ignorableOpts = append([]string{
	"--border", "--list-border", "--input-border", "--header-border",
	"--footer-border", "--preview-border",
	"--tmux", "--height", "--gap", "--gap-line", "--scrollbar",
	"--multi", "--listen", "--listen-unsafe",
